// const: значение не меняется
const surname = 'Gavrilik';

// массив чисел
const numbers = [3, 8, 15, 4, 23];

// let: значение меняется в цикле
let sum = 0;
let evenCount = 0;

// цикл for
for (let i = 0; i < numbers.length; i++) {
  sum += numbers[i];

  // if/else внутри цикла
  if (numbers[i] % 2 === 0) {
    evenCount++;
  }
}

// ещё один if/else: оценка суммы
let verdict;
if (sum > 50) {
  verdict = 'big';
} else {
  verdict = 'small';
}

// объект с результатами
const result = {
  surname: surname,
  numbers: numbers,
  sum: sum,
  evenCount: evenCount,
  verdict: verdict,
};

console.log('Результат расчёта:', result);

// возвращаем объект с полем payload
return [
  {
    json: {
      payload: result,
    },
  },
];
